import { data, TakaroUserError, checkPermission } from '@takaro/helpers';
import {
  applyEscalation,
  broadcast,
  describeStep,
  discordLog,
  getPlayerName,
  getPrefix,
  loadRecord,
  nextEscalation,
  parseReason,
  pickEscalation,
  pruneExpired,
  renderTemplate,
  saveRecord,
  sendTo,
} from './warn-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod, chatMessage } = data;
  const cfg = mod.userConfig;

  if (!checkPermission(pog, 'WARN_ISSUE')) {
    throw new TakaroUserError('You do not have permission to warn players.');
  }

  const target = args.player;
  if (!target || !target.playerId) {
    throw new TakaroUserError('Please name a valid player to warn.');
  }
  if (target.playerId === player.id) {
    throw new TakaroUserError('You cannot warn yourself.');
  }

  const reason = parseReason(chatMessage?.msg, args.reason);
  if (!reason) {
    throw new TakaroUserError('Please give a reason for the warning.');
  }

  const now = Date.now();
  const moduleId = mod.moduleId;
  const [targetName, prefix, loaded] = await Promise.all([
    getPlayerName(target.playerId, target.name || 'Unknown player'),
    getPrefix(gameServerId),
    loadRecord(gameServerId, moduleId, target.playerId),
  ]);
  const { record } = loaded;
  pruneExpired(record, cfg.warningExpiryDays, now);

  const warning = {
    id: record.nextId,
    reason,
    staffId: player.id,
    staffName: player.name,
    createdAt: new Date(now).toISOString(),
    delivered: false,
  };
  record.nextId += 1;
  record.warnings.push(warning);
  const count = record.warnings.length;

  const values = { player: targetName, staff: player.name, reason, count, id: warning.id, prefix };

  if (target.online !== false) {
    try {
      await sendTo(gameServerId, target.gameId, renderTemplate(cfg.warnMessage, values));
      warning.delivered = true;
    } catch (err) {
      console.error(`warn-system: PM to ${targetName} failed: ${err}`);
    }
  }

  await saveRecord(gameServerId, moduleId, target.playerId, loaded.variableId, record);

  if (cfg.broadcastWarnings) {
    await broadcast(gameServerId, renderTemplate(cfg.broadcastMessage, values));
  }

  const step = pickEscalation(cfg.escalation, count);
  let escalationText = '';
  if (step) {
    if (warning.delivered && step.action !== 'kick') {
      try {
        await sendTo(gameServerId, target.gameId, `You reached ${count} warnings: ${describeStep(step)}.`);
      } catch {
        // The ban still happens; the notice is best effort.
      }
    }
    const result = await applyEscalation({ step, gameServerId, target, targetName, count, reason, now });
    escalationText = result.text;
  }

  const staffLines = [`Warned ${targetName} (#${warning.id}): ${reason}. Active warnings: ${count}.`];
  if (!warning.delivered) staffLines.push(`${targetName} is offline and will be told on next join.`);
  if (escalationText) {
    staffLines.push(escalationText);
  } else {
    const next = nextEscalation(cfg.escalation, count);
    if (next) staffLines.push(`Next step at ${next.warnings} warnings: ${describeStep(next)}.`);
  }
  for (const line of staffLines) {
    await pog.pm(line);
  }

  const log = [`⚠️ **${targetName}** warned by **${player.name}** (#${warning.id}, ${count} active): ${reason}`];
  if (escalationText) log.push(`➡️ ${escalationText}`);
  await discordLog(cfg.discordChannelId, log.join('\n'));
}

await main();

import { data, TakaroUserError, checkPermission } from '@takaro/helpers';
import {
  daysLeft,
  describeStep,
  formatDate,
  loadRecord,
  nextEscalation,
  pruneExpired,
  resolvePlayerByName,
  saveRecord,
} from './warn-helpers.js';

const SELF_WORDS = ['', 'me', 'self', 'myself'];
const MAX_LINES = 10;

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const cfg = mod.userConfig;
  const input = String(args.player ?? '').trim();
  const isSelf = SELF_WORDS.includes(input.toLowerCase());

  let targetId = player.id;
  let targetName = player.name;
  if (!isSelf) {
    if (!checkPermission(pog, 'WARN_ISSUE') && !checkPermission(pog, 'WARN_MANAGE')) {
      throw new TakaroUserError('You can only view your own warnings. Use the command without a name.');
    }
    const found = await resolvePlayerByName(gameServerId, input);
    if (found.error) throw new TakaroUserError(found.error);
    targetId = found.playerId;
    targetName = found.name;
  }
  const own = targetId === player.id;

  const now = Date.now();
  const { variableId, record } = await loadRecord(gameServerId, mod.moduleId, targetId);
  const removed = pruneExpired(record, cfg.warningExpiryDays, now);
  const count = record.warnings.length;

  // Reading your own list counts as being told; it also saves the pruned list.
  const undelivered = own ? record.warnings.filter((w) => !w.delivered) : [];
  undelivered.forEach((w) => {
    w.delivered = true;
  });
  if (variableId && (removed > 0 || undelivered.length > 0)) {
    await saveRecord(gameServerId, mod.moduleId, targetId, variableId, record);
  }

  const who = own ? 'You have' : `${targetName} has`;
  if (count === 0) {
    await pog.pm(`${who} no active warnings.`);
    return;
  }

  await pog.pm(`${who} ${count} active warning${count === 1 ? '' : 's'}:`);
  const shown = record.warnings.slice(-MAX_LINES);
  for (const w of shown) {
    const left = daysLeft(w, cfg.warningExpiryDays, now);
    const expiry = left === null ? '' : ` (expires in ${left}d)`;
    await pog.pm(`#${w.id} ${formatDate(w.createdAt)} by ${w.staffName}: ${w.reason}${expiry}`);
  }
  if (count > shown.length) {
    await pog.pm(`...and ${count - shown.length} older warning(s).`);
  }

  const next = nextEscalation(cfg.escalation, count);
  if (next) {
    await pog.pm(`At ${next.warnings} warnings: ${describeStep(next)}.`);
  }
}

await main();

import { data, TakaroUserError, checkPermission } from '@takaro/helpers';
import { discordLog, getPlayerName, loadRecord, pruneExpired, saveRecord } from './warn-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const cfg = mod.userConfig;

  if (!checkPermission(pog, 'WARN_MANAGE')) {
    throw new TakaroUserError('You do not have permission to remove warnings.');
  }

  const target = args.player;
  if (!target || !target.playerId) {
    throw new TakaroUserError('Please name a valid player.');
  }
  const id = Number(args.id);
  if (!Number.isInteger(id) || id < 1) {
    throw new TakaroUserError('Please give the warning id, for example: unwarn Bob 2');
  }

  const targetName = await getPlayerName(target.playerId, target.name || 'Unknown player');
  const { variableId, record } = await loadRecord(gameServerId, mod.moduleId, target.playerId);
  pruneExpired(record, cfg.warningExpiryDays, Date.now());

  const index = record.warnings.findIndex((w) => Number(w.id) === id);
  if (index === -1 || !variableId) {
    throw new TakaroUserError(`${targetName} has no active warning #${id}.`);
  }
  const [removed] = record.warnings.splice(index, 1);
  await saveRecord(gameServerId, mod.moduleId, target.playerId, variableId, record);

  const count = record.warnings.length;
  await pog.pm(`Removed warning #${id} from ${targetName}. Active warnings: ${count}.`);
  await discordLog(
    cfg.discordChannelId,
    `✅ **${player.name}** removed warning #${id} from **${targetName}** (${count} active). It was: ${removed.reason}`,
  );
}

await main();

